using namespace std;

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	int T;
	cin >> T;
	while (T--) {
		int n;
		cin >> n;

		vector<int> a(n);
		map<int, vector<int>> p;
		for (int i = 0; i < n; i++) {
			cin >> a[i];
			p[a[i]].push_back(i);
		}

		int ans = 0;
		set<int> ts;
		for (int i = 0; i < n - 1; i++) {
			if (a[i] > a[i + 1]) ts.insert(i);
		}

		while (!ts.empty()) {
			int i = *ts.begin();
			int x;
			if (a[i] > 0) {
				x = a[i];
			} else {
				x = a[i + 1];
			}

			for (int j: p[x]) {
				a[j] = 0;
				ts.erase(j - 1);
				ts.erase(j);
				if (j > 0 && a[j - 1] > a[j]) ts.insert(j - 1);
				if (j + 1 < n && a[j] > a[j + 1]) ts.insert(j);
			}
			ans++;
		}

		cout << ans << nl;
	}
}

#include <bits/stdc++.h>

#define all(x) (x).begin(), (x).end()
#define allr(x) (x).rbegin(), (x).rend()
#define gsize(x) (int)((x).size())

const char nl = '\n';
typedef long long ll;
typedef long double ld;

using namespace std;

const int inf = 1000000000;

bool f(vector<int> a, int k, int ans) {
	int n = gsize(a);
	int dk = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] * 2 < ans) {
			a[i] = inf;
			k--;
			dk++;
		}
	}

	if (k < 0) return false;
	if ((k > 0 && dk > 0) || k >= 2) return true;

	if (k == 1 && dk == 0) {
		return *max_element(all(a)) >= ans;
	}

	for (int i = 0; i < n - 1; i++) {
		if (min(a[i], a[i + 1]) >= ans) return true;
	}

	return false;
}

void solve() {
	int n, k;
	cin >> n >> k;
	vector<int> a(n);
	for (int i = 0; i < n; i++) cin >> a[i];

	int lb = 0, ub = inf, tans = 0;
	while (lb <= ub) {
		int tm = (lb + ub) / 2;
		if (f(a, k, tm)) {
			tans = tm;
			lb = tm + 1;
		} else {
			ub = tm - 1;
		}
	}

	cout << tans << nl;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	int T;
	cin >> T;
	while (T--) solve();
}

#include <bits/stdc++.h>

#define all(x) (x).begin(), (x).end()
#define allr(x) (x).rbegin(), (x).rend()
#define gsize(x) (int)((x).size())

const char nl = '\n';
typedef long long ll;
typedef long double ld;

using namespace std;

const int maxn = 200000; 

int t[(maxn + 1) * 4];

void update(int v, int tl, int tr, int i, int x) {
	t[v] += x;
	if (tl != tr - 1) {
		int tm = (tl + tr) / 2;
		if (i < tm) update(2*v + 1, tl, tm, i, x);
		else update(2*v + 2, tm, tr, i, x);
	}
}

int query(int v, int tl, int tr, int l, int r) {
	if (l >= r) return 0;
	if (tl == l && tr == r) return t[v];
	else {
		int tm = (tl + tr) / 2;
		int r1 = query(2*v + 1, tl, tm, l, min(r, tm));
		int r2 = query(2*v + 2, tm, tr, max(l, tm), r);
		return r1 + r2;
	}
}


int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	vector<vector<int>> d(2*maxn + 1);

	for (int i = 1; i <= maxn; i++) {
		for (int j = i; j <= 2*maxn; j += i) {
			d[j].push_back(i);
		}
	}

	vector<vector<pair<int, int>>> segs(maxn + 1);

	for (int k = 1; k <= maxn; k++) {
		for (int ti = 0; ti < gsize(d[2*k]); ti++) {
			int i = d[2*k][ti], ct = 0;

			for (int tj = ti + 1; tj < gsize(d[2*k]); tj++) {
				int j = d[2*k][tj];
				if (j >= k) break;
				if (i + j > k || (k % i == 0 && k % j == 0)) ct++;
			}

			if (ct > 0)	{
				segs[i].emplace_back(k, ct);
			}
		}
	}



	int T;
	cin >> T;

	vector<ll> ans(T);
	vector<array<int, 3>> queries;

	for (int i = 0; i < T; i++) {
		ll l, r;
		cin >> l >> r;
		queries.push_back({l, r, i});
		ans[i] = (r - l + 1) * (r - l) * (r - l - 1) / 6;
	}

	sort(all(queries));

	int ti = T - 1;
	for (int i = maxn; i >= 1; i--) {

		// Update ST
		for (auto [r, ct]: segs[i]) {
			update(0, 0, maxn + 1, r, ct);
		}

		// Get Answers
		while (ti >= 0 && queries[ti][0] == i) {
			ans[queries[ti][2]] -= query(0, 0, maxn + 1, i, queries[ti][1] + 1);
			ti--;
		}
	}
	for (int i = 0; i < T; i++) cout << ans[i] << nl;
}

#include <bits/stdc++.h>

#define all(x) (x).begin(), (x).end()
#define allr(x) (x).rbegin(), (x).rend()
#define gsize(x) (int)((x).size())

const char nl = '\n';
typedef long long ll;
typedef long double ld;

using namespace std;

const int maxn = 1000000;
int f[maxn], d[maxn];
vector<int> g[maxn], g2[maxn], val[maxn];
int n, q;

vector<int> ans, x;

void solve() {

	for (int v = n - 1; v >= 0; v--) {
		for (int u: g[v]) {
			if (gsize(val[u]) > gsize(val[v])) swap(val[u], val[v]);
			for (int fu = 0; fu < gsize(val[u]); fu++) {
				for (int qi = 0; qi < q; qi++) {
					while (true) {
						int fv = max(0, ans[qi] - fu - x[qi]);
						if (fv < gsize(val[v]) && 
							val[v][fv] + val[u][fu] - 2*d[v] >= ans[qi]) ans[qi]++;
						else break;
					}
				}
			}
			for (int fu = 0; fu < gsize(val[u]); fu++) {
				val[v][fu] = max(val[v][fu], val[u][fu]);
			}
			val[u].clear();
			val[u].shrink_to_fit();
		}
		{
			int fu = f[v];
			for (int qi = 0; qi < q; qi++) {
				while (true) {
					int fv = max(0, ans[qi] - fu - x[qi]);			
					if (fv < gsize(val[v]) && 
						val[v][fv] - d[v] >= ans[qi]) ans[qi]++;
					else break;
				}
			}
			if (fu == gsize(val[v])) {
				val[v].push_back(d[v]);
			}
		}
	}

	for (int i = 0; i < q; i++) {
		ans[i]--;
	}
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	cin >> n;

	vector<int> deg(n);
	for (int i = 1; i < n; i++) {
		int p;
		cin >> p;
		d[i] = d[p - 1] + 1;
		g[p - 1].push_back(i);
		g2[i].push_back(p - 1);
	}

	{
		queue<int> qe;
		vector<bool> used(n, false);
		for (int i = 0; i < n; i++) {
			if (gsize(g2[i]) + gsize(g[i]) == 1) {
				qe.push(i);
				used[i] = true;
			}
		}

		while (!qe.empty()) {
			int v = qe.front();
			qe.pop();
			for (int u: g[v]) {
				if (used[u]) continue;
				f[u] = f[v] + 1;
				qe.push(u);
				used[u] = true;
			}

			for (int u: g2[v]) {
				if (used[u]) continue;
				f[u] = f[v] + 1;
				qe.push(u);
				used[u] = true;
			}
		}
	}

	cin >> q;
	for (int i = 0; i < q; i++) {
		int tx;
		cin >> tx;
		x.push_back(tx);
		ans.push_back(0);
	}

	solve();

	for (int tans: ans) cout << tans << ' ';
	cout << nl;
}
